function tutor(){const c=currentConcept(),chat=state().chat.slice(-16);return shell(`<div class="tutor-layout"><div class="tutor-chat"><div class="screen-scroll card" id="chatBox">${chat.length?chat.map(m=>`<div class="row tutor-message ${m.role==='user'?'me':'assistant'}"><b>${m.role==='user'?'나':'119'}</b><p>${esc(m.text)}</p></div>`).join(''):'<div class="tutor-empty"><span class="eyebrow">119 학습도우미</span><h2>${esc(c.title)}</h2><p>현재 개념과 공식근거, 내 오답·개인자료를 함께 보고 질문할 수 있습니다.</p><div class="tutor-quick"><button data-tutor-prompt="이 개념을 시험 직전 30초 요약으로 설명해줘">30초 요약</button><button data-tutor-prompt="이 개념에서 시험에 자주 헷갈리는 비교 포인트를 표처럼 설명해줘">헷갈리는 비교</button><button data-tutor-prompt="내가 이 개념에서 틀리기 쉬운 포인트를 중심으로 설명해줘">오답 중심</button><button data-tutor-prompt="공식근거에 있는 내용만 사용해서 상세하게 설명해줘">공식근거만</button></div></div>'}</div><div class="tutor-compose"><input id="tutorInput" class="input" placeholder="119에게 물어보기 · 예: 준비작동식과 일제살수식 차이를 설명해줘"><button class="btn primary" data-tutor-send>보내기</button></div></div><aside class="tutor-context card"><span class="eyebrow">현재 학습</span><h3>${esc(c.title)}</h3><p class="tiny muted">${esc(runtime.aiStatus)}</p>${!runtime.aiEngine?'<button class="btn block" data-ai-load>AI 답변 강화</button>':''}<button class="btn ghost block" data-source-concept="${c.id}">공식 원문 보기</button></aside></div>`,'AI 질문',`${c.scopeTitle} › ${c.title}`)}
function examReportView(rec){
  const ids=rec.questionIds||[],answers=rec.answers||{},items=ids.map(id=>{const q=V.questionById[id];return q?{q,selected:answers[id]}:null}).filter(Boolean);
  const missed=items.filter(x=>x.selected===undefined||x.selected!==x.q.a),scopeCounts=new Map();
  for(const x of missed){const sc=V.curriculum.scopeById?.[x.q.scopeId],key=sc?.title||x.q.scopeId||'기타';scopeCounts.set(key,(scopeCounts.get(key)||0)+1)}
  const weak=[...scopeCounts.entries()].sort((a,b)=>b[1]-a[1]).slice(0,5),total=rec.total||ids.length||65;
  const row=x=>{const q=x.q,mine=x.selected===undefined?'미응답':`${Number(x.selected)+1}. ${q.choices?.[x.selected]??''}`,right=`${q.a+1}. ${q.choices?.[q.a]??''}`,mineWhy=x.selected===undefined?'':q.choiceExplanations?.[x.selected]||'',rightWhy=q.choiceExplanations?.[q.a]||q.ex||'',concept=V.curriculum.byId[q.conceptId];
    return `<article class="exam-miss"><div class="exam-miss-head"><span>${esc(V.subjectLabel(q.subject))}</span><span>${esc(concept?.scopeTitle||'')}</span></div><h3>${esc(q.q)}</h3><div class="exam-answer-line wrong-answer"><b>내 답</b><span>${esc(mine)}</span></div><div class="exam-answer-line right-answer"><b>정답</b><span>${esc(right)}</span></div>${mineWhy?`<p class="exam-why"><b>왜 틀렸나</b> ${esc(mineWhy)}</p>`:''}<p class="exam-why"><b>정답 근거</b> ${esc(rightWhy)}</p><div class="toolbar"><button class="btn small primary" data-concept="${esc(q.conceptId)}">개념 복습</button><button class="btn small" data-retry="${esc(q.id)}">다시 풀기</button><button class="btn small ghost" data-source-concept="${esc(q.conceptId)}">원문 근거</button></div></article>`;
  };
  return `<div class="exam-report screen-scroll"><div class="toolbar exam-report-top"><button class="btn small ghost" data-report-close>← 최근 시험</button><span class="spacer"></span><span class="tag">${rec.mode==='real'?'실전':'연습'}</span></div><section class="card exam-report-summary"><h2>${rec.score}점</h2><div class="exam-report-grid"><div><span>전체</span><b>${rec.correct}/${total}</b></div><div><span>소방학</span><b>${rec.fireCorrect}/25</b></div><div><span>응급처치</span><b>${rec.emsCorrect}/40</b></div><div><span>시간</span><b>${Math.floor((rec.elapsedSec||0)/60)}분 ${(rec.elapsedSec||0)%60}초</b></div></div><p class="tiny muted">미응답 ${rec.unanswered||0} · 오답 ${rec.incorrectQuestionIds?.length??missed.filter(x=>x.selected!==undefined).length}</p></section>${weak.length?`<section class="card"><b>취약 단원</b><div class="weak-list">${weak.map(([name,n])=>`<span class="weak-chip">${esc(name)} · ${n}</span>`).join('')}</div></section>`:''}<section class="card exam-missed-section"><div class="toolbar"><b>오답·미응답 분석</b><span class="spacer"></span><span class="tiny muted">${missed.length}문항</span></div><div class="exam-miss-list">${missed.length?missed.map(row).join(''):'<div class="empty" style="height:120px">전 문항 정답입니다.</div>'}</div></section></div>`;
}
