function evidenceQueries(p){return [p?.summary,...(p?.must||[]),...(p?.detail||[])].filter(Boolean).slice(0,8)}
function sourceModal(id){return openPdfEvidence(id)}
async function renderResourcePdf(key,pageOverride=1){
  const root=document.querySelector('#resourcePdf');if(!root)return;
  const host=root.querySelector('#resourcePdfHost'),badge=root.querySelector('[data-resource-page-label]'),catalog=V.SourceCatalog119?.get?.(key),official=catalog?.officialPage||V.SourcePDF?.sourcePage?.(key)||'';
  if(!catalog||!V.SourcePDF){host.innerHTML='<div class="empty">연결된 원문이 없습니다.</div>';return}
  host.innerHTML='<div class="pdf-loading"><b>공식 교재 여는 중…</b><small>필요한 페이지만 불러옵니다.</small><div class="progressbar"><i style="width:35%"></i></div></div>';
  try{
    const result=await V.SourcePDF.render(key,Number(pageOverride)||1,host,[],{timeoutMs:90000});
    root.dataset.page=String(result.page);root.dataset.pages=String(result.pages);
    badge.textContent=result.bookPage?`교재 ${result.bookPage}쪽`:`PDF ${result.page}/${result.pages}쪽`;
    const prev=root.querySelector('[data-resource-pdf-page="-1"]'),next=root.querySelector('[data-resource-pdf-page="1"]');
    if(prev)prev.disabled=result.page<=1;if(next)next.disabled=result.page>=result.pages;
    root.querySelector('.pdf-pager')?.classList.remove('hidden');
  }catch(err){
    badge.textContent='원문을 불러오지 못했습니다';
    host.innerHTML=`<div class="source-connect official-fallback"><b>교재를 불러오지 못했습니다.</b><p>네트워크 상태를 확인한 뒤 다시 시도하세요.</p>${official?`<a class="btn ghost" target="_blank" rel="noopener" href="${esc(official)}">중앙소방학교 원문 열기</a>`:''}</div>`;
    root.querySelector('.pdf-pager')?.classList.add('hidden');
  }
}
async function openResourcePdf(key){
  const row=V.SourceCatalog119?.get?.(key);if(!row)return;
  document.querySelector('#resourcePdf')?.remove();
  document.body.insertAdjacentHTML('beforeend',`<div class="modal-wrap" id="resourcePdf" data-resource-pdf-backdrop data-doc-key="${esc(key)}" data-page="1"><div class="modal pdf-evidence-modal"><div class="toolbar pdf-modal-head"><div><span class="eyebrow">공식 자료</span><h2>${esc(row.label)}</h2><small data-resource-page-label class="muted">PDF 여는 중</small></div><span class="spacer"></span><button class="btn small ghost pdf-close-btn" data-resource-pdf-close>닫기</button></div><div id="resourcePdfHost" class="pdf-evidence-host"><div class="empty">공식 교재 확인 중…</div></div><div class="toolbar pdf-pager hidden"><button class="btn ghost" data-resource-pdf-page="-1">← 이전 페이지</button><button class="btn ghost" data-resource-pdf-page="1">다음 페이지 →</button></div></div></div>`);
  await renderResourcePdf(key,1);
}
async function renderPdfEvidence(id,pageOverride=null){
  const root=document.querySelector('#pdfEvidence');if(!root)return;
  const c=V.curriculum.byId[id],p=V.contentPacks.get(id),range=(c?.sourceRanges||[])[0],key=range?.doc||'',host=root.querySelector('#pdfEvidenceHost'),badge=root.querySelector('[data-pdf-page-label]'),queries=evidenceQueries(p);
  if(!key||!V.SourcePDF){host.innerHTML='<div class="empty">연결된 원문이 없습니다.</div>';return}
  const availability=await V.SourcePDF.availability(key),official=availability.officialPage||V.SourcePDF.sourcePage(key),catalog=V.SourceCatalog119?.get?.(key),staticRange=catalog?.transport==='range-static';
  if(!availability.local&&!availability.direct){badge.textContent='공식 원문';host.innerHTML=`<div class="source-connect official-fallback"><b>원문을 바로 불러올 수 없습니다.</b>${official?`<a class="btn primary block" target="_blank" rel="noopener" href="${esc(official)}">중앙소방학교 원문 열기</a>`:''}</div>`;root.querySelector('.pdf-pager')?.classList.add('hidden');return}
  host.innerHTML=staticRange
    ?'<div class="pdf-loading"><b>공식 교재 여는 중…</b><small>필요한 페이지만 빠르게 불러옵니다.</small><div class="progressbar"><i style="width:35%"></i></div><span>원문 준비 중</span></div>'
    :`<div class="pdf-loading"><b>${availability.local?'저장된 교재 여는 중…':'공식 교재를 이 기기에 저장하는 중…'}</b><small>처음 한 번 저장하면 다음부터 같은 교재는 바로 열립니다.</small><div class="progressbar"><i data-pdf-progress style="width:${availability.local?100:4}%"></i></div><span data-pdf-progress-label>${availability.local?'교재 확인 중':'다운로드 준비 중'}</span></div>`;
  try{
    const bookFrom=Number(range?.from)||0,initialPdfPage=bookFrom?(V.SourcePDF.pdfPage?.(key,bookFrom)||bookFrom):0;
    let page=Number(pageOverride)||Number(root.dataset.page)||initialPdfPage||0;
    const progress=({loaded,total,percent})=>{const bar=root.querySelector('[data-pdf-progress]'),label=root.querySelector('[data-pdf-progress-label]');if(bar&&percent!=null)bar.style.width=Math.max(4,percent)+'%';if(label)label.textContent=percent!=null?`교재 저장 중 ${percent}%`:`교재 저장 중 · ${Math.max(1,Math.round((loaded||0)/1048576))}MB`};
    if(!page){badge.textContent='근거 위치 찾는 중…';const located=await V.SourcePDF.locate(key,queries);page=located.page;root.dataset.autoLocated='true'}
    badge.textContent=staticRange?'공식 교재 여는 중…':(availability.local?'저장된 교재 여는 중…':'교재 저장 중…');
    const result=await V.SourcePDF.render(key,page,host,queries,{timeoutMs:90000,onProgress:progress});
    root.dataset.page=String(result.page);root.dataset.pages=String(result.pages);
    badge.textContent=result.bookPage?`교재 ${result.bookPage}쪽 · 공식 근거`:`PDF ${result.page}/${result.pages}쪽 · 공식 근거`;
    const prev=root.querySelector('[data-pdf-page="-1"]'),next=root.querySelector('[data-pdf-page="1"]');if(prev)prev.disabled=result.page<=1;if(next)next.disabled=result.page>=result.pages;
    root.querySelector('.pdf-pager')?.classList.remove('hidden')
  }catch(err){
    badge.textContent='원문을 불러오지 못했습니다';
    host.innerHTML=`<div class="source-connect official-fallback"><b>교재를 불러오지 못했습니다.</b><p>네트워크 상태를 확인한 뒤 다시 시도하세요.</p><div class="toolbar"><button class="btn primary" data-pdf-retry>다시 시도</button>${official?`<a class="btn ghost" target="_blank" rel="noopener" href="${esc(official)}">공식 원문 열기</a>`:''}</div></div>`;
    root.querySelector('.pdf-pager')?.classList.add('hidden')
  }
}
async function openPdfEvidence(id){const c=V.curriculum.byId[id],range=(c?.sourceRanges||[])[0],key=range?.doc||'',bookFrom=Number(range?.from)||0,hasMappedBookPage=Object.prototype.hasOwnProperty.call(V.SourcePDF?.pageOffsets||{},key),initialPdf=bookFrom?(V.SourcePDF.pdfPage?.(key,bookFrom)||bookFrom):0;document.querySelector('#sourceModal')?.remove();document.querySelector('#pdfEvidence')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-wrap" id="pdfEvidence" data-pdf-backdrop data-concept-id="${esc(id)}" data-page="${initialPdf||''}"><div class="modal pdf-evidence-modal"><div class="toolbar pdf-modal-head"><div><span class="eyebrow">공식 근거</span><h2>${esc(c?.title||id)}</h2><small data-pdf-page-label class="muted">${bookFrom?(hasMappedBookPage?`교재 ${bookFrom}쪽`:`PDF ${bookFrom}쪽`):'근거 위치 찾기'}</small></div><span class="spacer"></span><button class="btn small ghost pdf-close-btn" data-pdf-close>닫기</button></div><div id="pdfEvidenceHost" class="pdf-evidence-host"><div class="empty">저장된 교재 확인 중…</div></div><div class="toolbar pdf-pager hidden"><button class="btn ghost" data-pdf-page="-1">← 이전 페이지</button><button class="btn ghost" data-pdf-page="1">다음 페이지 →</button></div></div></div>`);await renderPdfEvidence(id)}
